//! Port lockfiles: per-firmware facts (anchors with the sha256 of the bytes they name, allocatable
//! regions, container limits), keyed by the sha256 of the stock `.syx`. Generated by
//! `tools/patchkit/port_resolve.py`; patchkit only reads them and verifies the anchor hashes.

use crate::error::*;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Port {
    pub port: PortInfo,
    pub limits: Limits,
    #[serde(default)]
    pub region: Vec<Region>,
    #[serde(default)]
    pub anchor: Vec<Anchor>,
    #[serde(default)]
    pub hook: Vec<Hook>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct PortInfo {
    pub device: String,
    pub version: String,
    pub syx_sha256: String,
    pub main_sha256: String,
    pub dsp_sha256: String,
    pub resolved_by: String,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Limits {
    pub container_max: u64,
    pub dsp_stored_max: u64,
    pub dsp_depacked_max: u64,
    pub main_staged_max: u64,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Region {
    pub name: String,
    pub cpu: String,
    pub start: u64,
    pub end: u64,
    #[serde(default)]
    pub excludes: Vec<[u64; 2]>,
    pub mark: String,
}

fn code() -> String {
    "code".into()
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Anchor {
    pub name: String,
    pub cpu: String,
    /// `code` (bytes at `addr`), `data` (likewise) or `value` (`addr` is a number read from the
    /// `len` bytes at `src`, for example the operand of an instruction).
    #[serde(default = "code")]
    pub kind: String,
    pub addr: u64,
    /// SHARC code: the short-word (pc) address.
    #[serde(default)]
    pub pm: Option<u64>,
    pub len: u64,
    pub sha256: String,
    #[serde(default)]
    pub src: Option<u64>,
    pub mark: String,
    pub rule: String,
}

/// A declared hook point: the site anchor, a byte offset from it and how the displaced code is handled.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Hook {
    pub name: String,
    pub site: String,
    #[serde(default)]
    pub offset: i64,
    /// `before` (displaced instructions still run), `replace` (they are dropped) or `retarget`
    pub mode: String,
}

impl Port {
    pub fn parse(text: &str) -> Result<Port> {
        let p: Port = toml::from_str(text)?;
        if p.port.syx_sha256.len() != 64 {
            return Err(err!("port {}: syx_sha256 is not a sha256", p.port.version));
        }
        Ok(p)
    }

    pub fn id(&self) -> String {
        format!("{}-{}", self.port.device, self.port.version)
    }

    pub fn anchor(&self, name: &str) -> Option<&Anchor> {
        self.anchor.iter().find(|a| a.name == name)
    }

    pub fn hook(&self, name: &str) -> Option<&Hook> {
        self.hook.iter().find(|h| h.name == name)
    }

    pub fn region(&self, name: &str) -> Option<&Region> {
        self.region.iter().find(|r| r.name == name)
    }

    /// Free ranges of a region after its excludes, in address order.
    pub fn region_ranges(&self, name: &str) -> Vec<(u64, u64)> {
        let Some(r) = self.region(name) else {
            return vec![];
        };
        let mut ex = r.excludes.clone();
        ex.sort();
        let mut out = vec![];
        let mut at = r.start;
        for [s, e] in ex {
            if s > at {
                out.push((at, s.min(r.end)));
            }
            at = at.max(e);
        }
        if at < r.end {
            out.push((at, r.end));
        }
        out
    }
}

/// All ports known to a build, keyed by stock `.syx` sha256.
#[derive(Clone, Debug, Default)]
pub struct Registry {
    pub ports: Vec<Port>,
}

impl Registry {
    pub fn from_texts<'a>(texts: impl IntoIterator<Item = &'a str>) -> Result<Registry> {
        let mut ports = vec![];
        for t in texts {
            ports.push(Port::parse(t)?);
        }
        Ok(Registry { ports })
    }

    pub fn find(&self, syx_sha256: &str) -> Option<&Port> {
        self.ports.iter().find(|p| p.port.syx_sha256 == syx_sha256)
    }

    pub fn by_id(&self, id: &str) -> Option<&Port> {
        self.ports.iter().find(|p| p.id() == id)
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl Registry {
    pub fn from_dir(dir: &std::path::Path) -> Result<Registry> {
        let mut texts = vec![];
        let rd = std::fs::read_dir(dir).map_err(|e| err!("{}: {e}", dir.display()))?;
        let mut paths: Vec<_> = rd.filter_map(|e| e.ok()).map(|e| e.path()).collect();
        paths.sort();
        for p in paths {
            if p.extension().is_some_and(|e| e == "toml") {
                texts.push(std::fs::read_to_string(&p).map_err(|e| err!("{}: {e}", p.display()))?);
            }
        }
        Registry::from_texts(texts.iter().map(|s| s.as_str()))
    }
}
